BLOCKS.push({
id:'2.1.2', ch:2, title:'Структура фермента и активный центр', tags:['2_1_2'],
lead:'Из скольких аминокислот состоит активный центр, на какие участки он делится и какие группы в него входят.',
theory:`
<p>Молекула фермента обычно во много раз больше молекулы субстрата. В контакт с субстратом вступает лишь небольшая часть молекулы фермента — обычно <b>от 5 до 10 аминокислотных остатков</b>, формирующих активный центр. Роль остальных остатков — обеспечение правильной конформации молекулы для оптимального протекания реакции. Если фермент состоит из нескольких полипептидных цепей, окончательное формирование активного центра происходит при формировании <b>четвертичной структуры</b>.</p>

<div class="def"><span class="k">Определение</span><p><b>Активный центр фермента</b> — участок фермента, который включает несколько аминокислотных остатков, участвующих в присоединении и превращении субстрата. Это углубление, выстланное остатками аминокислот, сближенными друг с другом во время формирования конформации белка-фермента. Для катализа активный центр должен быть <b>комплементарен</b> молекуле субстрата.</p></div>

<h3>Какие группы чаще всего входят в активный центр</h3>
<div class="tw"><table>
<tr><th>Тип</th><th>Группы и аминокислоты</th></tr>
<tr><td class="n">Полярные заряженные</td><td>Карбоксильная группа глутамата и аспартата, аминогруппа лизина, гуанидиновая группа аргинина, имидазольная группа гистидина</td></tr>
<tr><td class="n">Полярные незаряженные</td><td>Гидроксильная группа серина, треонина, тирозина</td></tr>
<tr><td class="n">Неполярные</td><td>Ароматические кольца фенилаланина, триптофана</td></tr>
</table></div>

<h2 class="sec">Два участка активного центра</h2>
<figure>
<svg viewBox="0 0 660 250" role="img" aria-label="Участок связывания и каталитический участок">
 <path d="M120 26 A100 100 0 1 0 120 226 L120 168 Q210 126 120 84 Z" fill="var(--tint)" stroke="var(--teal)" stroke-width="2"/>
 <text class="sv-key" x="86" y="246">Фермент</text>
 <rect x="150" y="60" width="196" height="34" rx="8" fill="var(--plum-tint)" stroke="var(--plum)"/>
 <text class="sv-lbl" x="248" y="82" text-anchor="middle" fill="var(--plum)">участок связывания</text>
 <text class="sv-s" x="248" y="112" text-anchor="middle">якорный, контактный: удерживает субстрат</text>
 <rect x="150" y="150" width="196" height="34" rx="8" fill="var(--amber-tint)" stroke="var(--amber)"/>
 <text class="sv-lbl" x="248" y="172" text-anchor="middle" fill="var(--amber)">каталитический участок</text>
 <text class="sv-s" x="248" y="202" text-anchor="middle">превращает субстрат в продукт</text>
 <text class="sv-s" x="500" y="90" text-anchor="middle">Участки не всегда разделены</text>
 <text class="sv-s" x="500" y="108" text-anchor="middle">пространственно —</text>
 <text class="sv-s" x="500" y="126" text-anchor="middle">иногда они перекрываются</text>
</svg>
<figcaption>Активный центр условно делится на участок связывания и каталитический участок</figcaption></figure>
<ul>
 <li><b>Участок связывания</b> (контактный, якорный) представлен радикалами, функциональные группы которых обеспечивают связывание субстрата.</li>
 <li><b>Каталитический участок</b> образован радикалами, функциональные группы которых обеспечивают химическое превращение субстрата и выбор пути этого превращения.</li>
</ul>
<p>Субстрат образует с аминокислотными остатками активного центра <b>слабые связи</b>, а перечисленные функциональные группы могут участвовать в формировании водородных, ионных и гидрофобных взаимодействий.</p>
`,
inter:{type:'sort', title:'Разложите функции по участкам активного центра', buckets:[
 {name:'Участок связывания', items:['Удерживает субстрат','Другое название — якорный','Обеспечивает контакт с субстратом']},
 {name:'Каталитический участок', items:['Превращает субстрат в продукт','Выбирает путь химического превращения']}]},
quiz:[
 {q:'Сколько аминокислотных остатков обычно формирует активный центр?',o:['1–2','5–10','20–30','более 50'],c:1,e:'От 5 до 10 остатков; роль остальных — обеспечить правильную конформацию.'},
 {q:'Когда завершается формирование активного центра у олигомерного фермента?',o:['При образовании первичной структуры','При образовании вторичной структуры','При формировании четвертичной структуры','После связывания субстрата'],c:2,e:'Если фермент состоит из нескольких цепей, активный центр окончательно формируется на уровне четвертичной структуры.'},
 {q:'Какая группа гистидина участвует в работе активного центра?',o:['Гуанидиновая','Имидазольная','Гидроксильная','Сульфгидрильная'],c:1,e:'Гуанидиновая группа — у аргинина, гидроксильная — у серина, треонина, тирозина.'},
 {q:'Якорный участок активного центра отвечает за:',o:['Химическое превращение субстрата','Связывание субстрата','Синтез фермента','Регуляцию активности'],c:1,e:'Участок связывания (контактный, якорный) удерживает субстрат, а превращает его каталитический участок.'}
]});

